import{_ as e,c as r,o as t,ag as o}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/introduction.md","filePath":"zh-CN/guide/introduction.md","lastUpdated":1794112334000}'),i={name:"zh-CN/guide/introduction.md"};function n(s,a,h,l,c,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><h2 id="关于-nicasa" tabindex="-1">关于 Nicasa <a class="header-anchor" href="#关于-nicasa" aria-label="Permalink to &quot;关于 Nicasa&quot;">​</a></h2><p>Nicasa 是一款现代桌面图片查看与截图工具，以速度、简洁和强大的编辑能力为设计目标。它专为 macOS 打造，把顺滑、现代的看图体验带到你的桌面。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="🖼️-更好的看图方式" tabindex="-1">🖼️ <strong>更好的看图方式</strong> <a class="header-anchor" href="#🖼️-更好的看图方式" aria-label="Permalink to &quot;🖼️ **更好的看图方式**&quot;">​</a></h3><p>干净专注的界面让图片瞬间呈现。没有干扰，没有杂乱——只有你的内容，在打开的那一刻被优雅地呈现。</p><h3 id="📸-截图与捕捉" tabindex="-1">📸 <strong>截图与捕捉</strong> <a class="header-anchor" href="#📸-截图与捕捉" aria-label="Permalink to &quot;📸 **截图与捕捉**&quot;">​</a></h3><p>几秒内截取屏幕任意区域。快速而精确的截图工具内建于 Nicasa，保存与分享视觉灵感从未如此简单。</p><h3 id="🤖-ai-图像编辑" tabindex="-1">🤖 <strong>AI 图像编辑</strong> <a class="header-anchor" href="#🤖-ai-图像编辑" aria-label="Permalink to &quot;🤖 **AI 图像编辑**&quot;">​</a></h3><p>用强大的 AI 工具增强与修饰图片。从快速调整到智能编辑，Nicasa 帮你轻松完成图像变身。</p><h3 id="🔍-透明悬浮模式" tabindex="-1">🔍 <strong>透明悬浮模式</strong> <a class="header-anchor" href="#🔍-透明悬浮模式" aria-label="Permalink to &quot;🔍 **透明悬浮模式**&quot;">​</a></h3><p>设计师与画师的利器：把图片置顶于所有窗口之上，并可调节透明度——非常适合描图、参考对照和 UI 比对。</p><h3 id="🌐-chrome-扩展联动" tabindex="-1">🌐 <strong>Chrome 扩展联动</strong> <a class="header-anchor" href="#🌐-chrome-扩展联动" aria-label="Permalink to &quot;🌐 **Chrome 扩展联动**&quot;">​</a></h3><p>与 Nicasa Chrome 扩展无缝衔接，在一个界面里查看任意网站上的全部图片。随时提取、浏览并直接在 Nicasa 中打开图片，获得更快、更沉浸的看图体验。</p><h3 id="🎨-顺滑直观的设计" tabindex="-1">🎨 <strong>顺滑直观的设计</strong> <a class="header-anchor" href="#🎨-顺滑直观的设计" aria-label="Permalink to &quot;🎨 **顺滑直观的设计**&quot;">​</a></h3><p>由新一代技术驱动，Nicasa 带来流畅的转场、清晰的渲染和体贴的交互设计。</p><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><ul><li><strong>操作系统</strong>：macOS 10.13 或更高版本</li><li><strong>内存</strong>：最低 4GB RAM，推荐 8GB</li><li><strong>存储空间</strong>：安装需要 54.5 MB</li><li><strong>显示</strong>：最低 1280x720 分辨率</li></ul><h2 id="支持的语言" tabindex="-1">支持的语言 <a class="header-anchor" href="#支持的语言" aria-label="Permalink to &quot;支持的语言&quot;">​</a></h2><p>Nicasa 支持多种语言，包括英语、简体中文、繁体中文、日语、法语、韩语、德语、西班牙语、意大利语、越南语、泰语、印地语、土耳其语、俄语、葡萄牙语、荷兰语、德语（瑞士）、芬兰语、马来语、希腊语、挪威语、印尼语、匈牙利语、丹麦语和乌克兰语。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>如果你是 Nicasa 新手，请从<a href="/zh-CN/guide/installation.html">安装指南</a>开始，让你的 Mac 跑起这款应用。</p>',22)])])}const m=e(i,[["render",n]]);export{p as __pageData,m as default};
